#!/usr/bin/env node
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = resolve(here, '..');

// The worker source is generated by csr-common's build-worker.mjs and stored as a
// string constant. We read it at build time and write it as a standalone JS file
// so customers can copy it to their static assets directory.
const workerScriptTs = readFileSync(
  resolve(pkgRoot, '..', 'csr-common', 'src', 'uploader', 'worker', 'worker-script.ts'),
  'utf8',
);

// Extract the string literal from: export const workerScript: string = "...";
const match = workerScriptTs.match(/export const workerScript: string = ([\s\S]+);$/m);
if (!match) {
  console.error('emit-worker-file: could not parse worker-script.ts');
  process.exit(1);
}
const code = JSON.parse(match[1]);

const distDir = resolve(pkgRoot, 'dist');
mkdirSync(distDir, { recursive: true });
const outPath = resolve(distDir, 'confidence-worker.js');
writeFileSync(outPath, code);
console.log(`emit-worker-file: wrote ${code.length} bytes to ${outPath}`);
